/**
 * The typed code model behind the Rust, Swift and Kotlin token exports. One walk over the
 * resolved tokens infers a struct per object shape (named by path, deduplicated by signature),
 * so the three emitters only print syntax. Platform-valued objects ({desktop, ios, android, web})
 * collapse to the emitting platform's value, falling back to desktop.
 */
import type { Roles } from "../derive.ts";
import type { Resolved, Sources } from "../tokens.ts";

export const HEADER =
  "@generated by phux tools design-gen from crates/phux-design/tokens/src — do not edit";
export type Platform = "desktop" | "ios" | "android" | "web";
export type Scalar = "color" | "string" | "bool" | "int" | "float" | "double" | "u64";
export type Ty =
  | { kind: "scalar"; scalar: Scalar }
  | { kind: "struct"; name: string }
  | { kind: "array"; of: Ty };
export interface Struct {
  name: string;
  fields: { key: string; ty: Ty }[];
  doc?: string;
}
export interface Model {
  structs: Struct[];
  roots: { key: string; ty: Ty; value: unknown; doc: string }[];
}

const COLOR = /^#[0-9A-F]{6}([0-9A-F]{2})?$/;
const PLATFORM_KEYS = new Set(["desktop", "ios", "android", "web"]);

/** Struct names by path pattern (`*` matches one segment, `[]` an array element). */
const NAMES: [string, string][] = [
  ["meta", "Meta"],
  ["color", "RoleModes"],
  ["contrast_more", "RoleModes"],
  ["reader", "RoleModes"],
  ["R.*", "Roles"],
  ["R.*.layer", "LayerRoles"],
  ["R.*.text", "TextRoles"],
  ["R.*.border", "BorderRoles"],
  ["R.*.wash", "WashRoles"],
  ["R.*.accent", "AccentRoles"],
  ["R.*.status", "StatusRoles"],
  ["R.*.match", "MatchRoles"],
  ["R.*.diff", "DiffRoles"],
  ["R.*.selection", "SelectionRoles"],
  ["R.*.flat", "FlatRoles"],
  ["R.*.flat.*", "FlatLayer"],
  ["R.*.flat.*.layer", "FlatScrim"],
  ["R.*.flat.*.border", "FlatBorder"],
  ["R.*.flat.*.wash", "WashRoles"],
  ["R.*.flat.*.status", "FlatStatus"],
  ["R.*.flat.*.match", "FlatMatch"],
  ["R.*.flat.*.diff", "FlatDiff"],
  ["terminal", "TerminalModes"],
  ["terminal.*", "TerminalPalette"],
  ["type", "TypeTokens"],
  ["type.family", "Families"],
  ["type.family.*", "Family"],
  ["type.weights", "Weights"],
  ["type.role", "TypeRoles"],
  ["type.role.*", "TypeRole"],
  ["radius", "Radius"],
  ["space", "Space"],
  ["space.focus_ring", "FocusRing"],
  ["icon", "Icon"],
  ["icon.size", "IconSize"],
  ["icon.button", "IconButton"],
  ["layout", "Layout"],
  ["layout.breakpoint", "Breakpoint"],
  ["layout.content_max", "ContentMax"],
  ["haptic", "Haptics"],
  ["haptic.*", "Haptic"],
  ["elevation", "ElevationModes"],
  ["elevation.*", "Elevation"],
  ["elevation.*.*[]", "Shadow"],
  ["elevation.*.glow", "Glow"],
  ["motion", "Motion"],
  ["motion.spring", "Springs"],
  ["motion.spring.*", "SpringPair"],
  ["motion.spring.*.*", "Spring"],
  ["motion.curve", "Curves"],
  ["motion.curve.*", "Curve"],
  ["motion.loop", "Loops"],
  ["motion.loop.pulse", "Pulse"],
  ["motion.loop.*", "Period"],
  ["material", "Material"],
  ["material.glass", "Glass"],
  ["material.glass.blur", "GlassBlur"],
  ["material.glass.tint", "GlassTints"],
  ["material.glass.tint.*", "GlassTint"],
  ["material.glass.tint_min", "GlassTintMin"],
  ["material.metal", "Metal"],
  ["material.metal.stops", "MetalStops"],
  ["material.metal.stops.*[]", "MetalStop"],
  ["material.metal.sheen", "Sheen"],
  ["material.metal.sheen.spring", "Spring"],
  ["identity", "Identity"],
  ["identity.host_palette[]", "HostColor"],
  ["identity.provider", "Providers"],
  ["status[]", "StatusMark"],
  ["vocabulary", "Vocabulary"],
  ["vocabulary.words", "Words"],
  ["vocabulary.plurals", "Plurals"],
  ["vocabulary.plurals.count", "CountPlurals"],
  ["derive", "Params"],
  ["derive.bars", "Bars"],
  ["derive.contrast_more", "ContrastMoreBars"],
  ["derive.slots", "Slots"],
  ["derive.status_alpha", "StatusAlpha"],
  ["derive.match_alpha", "MatchAlpha"],
  ["derive.layers", "LayerStepModes"],
  ["derive.layers.*", "LayerSteps"],
  ["derive.alpha", "AlphaModes"],
  ["derive.alpha.*", "Alphas"],
  ["derive.alpha.*.border", "BorderAlpha"],
  ["derive.alpha.*.wash", "WashAlpha"],
  ["derive.scrim", "ModeAlpha"],
  ["derive.glass", "DeriveGlass"],
  ["derive.glass.tint_min", "ModeAlpha"],
];
const INT_KEYS = new Set([
  "schema",
  "iterations",
  "max_shadow_layers",
  "rank",
  "weight",
  "regular",
  "medium",
  "semibold",
  "auto_count",
  "passes",
]);

function matches(pattern: string, path: string): boolean {
  const body = pattern
    .replaceAll(".", "\\.")
    .replaceAll("[]", "\\[\\]")
    .replaceAll("*", "[^.\\[]+");
  // R: one of the three role-set roots.
  const re = new RegExp(`^${body.replace(/^R/, "(?:color|contrast_more|reader)")}$`);
  return re.test(path);
}
function nameFor(path: string): string {
  for (const [p, n] of NAMES) if (matches(p, path)) return n;
  throw Error(`codegen: no struct name for ${path}`);
}

function isPlatform(v: unknown): v is Record<string, number> {
  return (
    !!v &&
    typeof v === "object" &&
    !Array.isArray(v) &&
    "desktop" in v &&
    Object.keys(v).every((k) => PLATFORM_KEYS.has(k))
  );
}

/** Collapse platform-valued objects to one platform's value; keys become identifier-safe. */
export function forPlatform(v: unknown, platform: Platform): unknown {
  if (isPlatform(v)) return v[platform] ?? v.desktop;
  if (Array.isArray(v)) return v.map((x) => forPlatform(x, platform));
  if (v && typeof v === "object")
    return Object.fromEntries(
      Object.entries(v).map(([k, x]) => [k.replaceAll(".", "_"), forPlatform(x, platform)]),
    );
  return v;
}

export function build(roots: { key: string; value: unknown; doc: string }[]): Model {
  const structs = new Map<string, Struct & { sig: string }>();
  function infer(v: unknown, path: string, key: string): Ty {
    if (typeof v === "string") {
      if (path === "derive.srgb_lut[]") return { kind: "scalar", scalar: "u64" };
      return { kind: "scalar", scalar: COLOR.test(v) ? "color" : "string" };
    }
    if (typeof v === "boolean") return { kind: "scalar", scalar: "bool" };
    if (typeof v === "number") {
      if (INT_KEYS.has(key) || path.startsWith("derive.slots."))
        return { kind: "scalar", scalar: "int" };
      return { kind: "scalar", scalar: path.startsWith("derive.") ? "double" : "float" };
    }
    if (Array.isArray(v)) {
      if (!v.length) {
        if (/^elevation\.[^.]+\.flat$/.test(path))
          return { kind: "array", of: { kind: "struct", name: "Shadow" } };
        if (key === "features") return { kind: "array", of: { kind: "scalar", scalar: "string" } };
        throw Error(`codegen: empty array at ${path}`);
      }
      const tys = v.map((x) => infer(x, `${path}[]`, key));
      const sig = JSON.stringify(tys[0]);
      if (tys.some((t) => JSON.stringify(t) !== sig))
        throw Error(`codegen: mixed array at ${path}`);
      return { kind: "array", of: tys[0]! };
    }
    if (v && typeof v === "object") {
      const fields = Object.entries(v).map(([k, x]) => ({
        key: k,
        ty: infer(x, path ? `${path}.${k}` : k, k),
      }));
      const name = nameFor(path),
        sig = JSON.stringify(fields);
      const seen = structs.get(name);
      if (seen && seen.sig !== sig) throw Error(`codegen: ${name} has two shapes (at ${path})`);
      if (!seen) structs.set(name, { name, fields, sig });
      return { kind: "struct", name };
    }
    throw Error(`codegen: null or unsupported value at ${path}`);
  }
  const typed = roots.map((r) => ({ ...r, ty: infer(r.value, r.key, r.key) }));
  return { structs: [...structs.values()].map(({ sig: _sig, ...s }) => s), roots: typed };
}

/** Accent hi/lo exist only on the metal look; every role set carries them (defaulting to the accent) so one type fits. */
function rolesValue(r: Roles): unknown {
  const { mode: _mode, ...rest } = r;
  return {
    ...rest,
    accent: { ...r.accent, hi: r.accent.hi ?? r.accent.accent, lo: r.accent.lo ?? r.accent.accent },
  };
}

export function tokenRoots(
  R: Resolved,
  S: Sources,
  sha: string,
): { key: string; value: unknown; doc: string }[] {
  const d = R.doc;
  const modes = (x: Record<string, Roles>) => ({
    dark: rolesValue(x.dark!),
    light: rolesValue(x.light!),
  });
  return [
    {
      key: "meta",
      doc: "Which design version and house look these values come from.",
      value: {
        design_version: S.version,
        schema: 2,
        house: d.house,
        house_name: d.house_name,
        solver: "phux-derive/2",
        params_sha256: sha,
      },
    },
    {
      key: "color",
      doc: "The house look's colour roles (spec §1.2), per mode.",
      value: modes(R.house),
    },
    {
      key: "contrast_more",
      doc: "The increased-contrast variant (spec §1.11), per mode.",
      value: modes(R.contrastMore),
    },
    { key: "reader", doc: "The docs-reader colour variant, per mode.", value: modes(R.reader) },
    {
      key: "terminal",
      doc: "The house grid palette, catalog ids phux and phux-light.",
      value: d.terminal,
    },
    { key: "type", doc: "Type families, weights and the seven roles (spec §1.4).", value: d.type },
    { key: "radius", doc: "Corner radii (spec §1.5).", value: d.radius },
    { key: "space", doc: "The 4 pt grid and named spacing (spec §1.6).", value: d.space },
    { key: "icon", doc: "Icon sizes.", value: d.icon },
    { key: "layout", doc: "Breakpoints and content widths.", value: d.layout },
    { key: "haptic", doc: "Haptic feedback per platform.", value: d.haptic },
    {
      key: "elevation",
      doc: "Shadow tiers (spec §1.7), at most four layers each.",
      value: d.elevation,
    },
    {
      key: "motion",
      doc: "Spring pairs, curves and loops (spec §1.8); durations in seconds.",
      value: d.motion,
    },
    { key: "material", doc: "Glass and metal (spec §1.9).", value: d.material },
    { key: "identity", doc: "Host, session and provider identity colours.", value: d.identity },
    {
      key: "status",
      doc: "The status ladder (spec §1.3): mark, word and colour role per state.",
      value: d.status,
    },
    {
      key: "vocabulary",
      doc: "English words and ICU plural messages.",
      value: { words: S.vocabulary.words, plurals: nestDotted(S.vocabulary.plurals) },
    },
    {
      key: "derive",
      doc: "The solver parameters every port runs with (spec §2.4).",
      value: d.derive,
    },
  ];
}

/** `{"count.needs_you": m}` -> `{count: {needs_you: m}}`, so fields don't repeat a prefix. */
function nestDotted(o: Record<string, string>): Record<string, Record<string, string>> {
  const out: Record<string, Record<string, string>> = {};
  for (const [k, v] of Object.entries(o)) {
    const [group, name] = k.split(".") as [string, string];
    (out[group] ??= {})[name] = v;
  }
  return out;
}

export function modelFor(R: Resolved, S: Sources, sha: string, platform: Platform): Model {
  return build(tokenRoots(R, S, sha).map((r) => ({ ...r, value: forPlatform(r.value, platform) })));
}

export const snake = (k: string) => k;
export function lowerCamel(k: string): string {
  const parts = k.split("_").filter(Boolean);
  return parts.map((p, i) => (i === 0 ? p : p[0]!.toUpperCase() + p.slice(1))).join("");
}
export const upperCamel = (k: string) => {
  const c = lowerCamel(k);
  return c[0]!.toUpperCase() + c.slice(1);
};

/** Number literal that always reads as floating point. */
export function float(n: number): string {
  if (!Number.isFinite(n)) throw Error(`codegen: non-finite ${n}`);
  const s = String(n);
  if (/e/i.test(s)) throw Error(`codegen: exponent literal ${s}`);
  return s.includes(".") ? s : `${s}.0`;
}
export const rgbaHex = (c: string) => `0x${c.slice(1)}${c.length === 7 ? "FF" : ""}`;
export const argbHex = (c: string) => `0x${c.length === 9 ? c.slice(7) : "FF"}${c.slice(1, 7)}`;
export const quote = (s: string) => JSON.stringify(s);
